import json, sys

def trunc(s, n=300):
    if s is None:
        return ""
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

def main(path):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                print("PARSE_ERROR", line[:100])
                continue
            t = obj.get("type")
            ts = obj.get("timestamp", "")
            if t == "attachment":
                hookName = obj.get("attachment", {}).get("hookName")
                print(f"[{ts}] ATTACHMENT hook={hookName}")
            elif t == "queue-operation":
                print(f"[{ts}] QUEUE-OP op={obj.get('operation')} content={trunc(obj.get('content'), 150)}")
            elif t == "user":
                msg = obj.get("message", {})
                content = msg.get("content")
                if isinstance(content, str):
                    print(f"[{ts}] USER: {trunc(content, 400)}")
                elif isinstance(content, list):
                    for c in content:
                        ctype = c.get("type")
                        if ctype == "text":
                            print(f"[{ts}] USER: {trunc(c.get('text'), 400)}")
                        elif ctype == "tool_result":
                            cont = c.get("content")
                            if isinstance(cont, list):
                                cont = " ".join(x.get("text","") for x in cont if isinstance(x, dict))
                            print(f"[{ts}] TOOL_RESULT: {trunc(cont, 250)}")
                        else:
                            print(f"[{ts}] USER({ctype}): {trunc(c, 150)}")
            elif t == "assistant":
                msg = obj.get("message", {})
                content = msg.get("content")
                if isinstance(content, list):
                    for c in content:
                        ctype = c.get("type")
                        if ctype == "text":
                            print(f"[{ts}] ASSISTANT: {trunc(c.get('text'), 400)}")
                        elif ctype == "tool_use":
                            print(f"[{ts}] TOOL_USE: {c.get('name')} input={trunc(json.dumps(c.get('input', {})), 250)}")
                        elif ctype == "thinking":
                            print(f"[{ts}] THINKING: {trunc(c.get('thinking'), 200)}")
                        else:
                            print(f"[{ts}] ASSISTANT({ctype}): {trunc(c, 150)}")
                elif isinstance(content, str):
                    print(f"[{ts}] ASSISTANT: {trunc(content, 400)}")
            elif t == "system":
                print(f"[{ts}] SYSTEM: {trunc(obj.get('content'), 200)}")
            else:
                print(f"[{ts}] {t}: {trunc(obj, 150)}")

if __name__ == "__main__":
    main(sys.argv[1])

import json, sys

def truncate(s, n=300):
    s = s.replace('\n', ' ')
    return s if len(s) <= n else s[:n] + '...'

def main(path):
    with open(path) as f:
        lines = f.readlines()
    for l in lines:
        l = l.strip()
        if not l:
            continue
        try:
            d = json.loads(l)
        except Exception:
            continue
        ts = d.get('timestamp', '')
        typ = d.get('type', '')
        if typ == 'queue-operation':
            print(f"[{ts}] QUEUE {d.get('operation')} {truncate(d.get('content',''),150)}")
            continue
        msg = d.get('message')
        if msg is None:
            att = d.get('attachment')
            if att and isinstance(att, dict):
                atype = att.get('type')
                if atype in ('hook_success','hook_failure'):
                    print(f"[{ts}] HOOK {att.get('hookName')} {truncate(att.get('content',''),200)}")
            continue
        role = msg.get('role')
        content = msg.get('content')
        if isinstance(content, str):
            print(f"[{ts}] {role.upper()}: {truncate(content, 400)}")
        elif isinstance(content, list):
            for c in content:
                ctype = c.get('type')
                if ctype == 'text':
                    print(f"[{ts}] {role.upper()} text: {truncate(c.get('text',''), 400)}")
                elif ctype == 'tool_use':
                    print(f"[{ts}] {role.upper()} tool_use: {c.get('name')} {truncate(json.dumps(c.get('input',{})), 250)}")
                elif ctype == 'tool_result':
                    cc = c.get('content')
                    if isinstance(cc, list):
                        txt = ' '.join(x.get('text','') for x in cc if isinstance(x, dict) and x.get('type')=='text')
                    else:
                        txt = str(cc)
                    err = c.get('is_error')
                    print(f"[{ts}] {role.upper()} tool_result{'(ERROR)' if err else ''}: {truncate(txt, 250)}")
                elif ctype == 'thinking':
                    pass
                else:
                    pass

if __name__ == '__main__':
    main(sys.argv[1])

