import json, sys, datetime

def get_text(msg):
    content = msg.get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for c in content:
            if c.get("type") == "text":
                parts.append(c.get("text",""))
        return " ".join(parts)
    return ""

def main(path):
    with open(path) as f:
        lines = [json.loads(l) for l in f if l.strip()]
    prev_ts = None
    for i, d in enumerate(lines):
        ts = d.get("timestamp")
        msg = d.get("message")
        if not msg:
            continue
        role = msg.get("role")
        content = msg.get("content")
        if role == "user" and isinstance(content, str):
            print(f"[{i}][{ts}] USER: {content[:600]}")
        elif role == "user" and isinstance(content, list):
            for c in content:
                if c.get("type") == "tool_result":
                    cc = c.get("content")
                    if isinstance(cc, list):
                        txt = " ".join(x.get("text","") for x in cc if isinstance(x,dict))
                    else:
                        txt = str(cc)
                    is_err = c.get("is_error")
                    if is_err or "error" in txt.lower()[:200] or "fatal" in txt.lower()[:200] or "conflict" in txt.lower()[:200]:
                        print(f"[{i}][{ts}] TOOL_RESULT(err?): {txt[:300]}")
        if prev_ts and ts:
            try:
                t1 = datetime.datetime.fromisoformat(prev_ts.replace("Z","+00:00"))
                t2 = datetime.datetime.fromisoformat(ts.replace("Z","+00:00"))
                gap = (t2-t1).total_seconds()
                if gap > 60:
                    print(f"[{i}][{ts}] <<GAP {gap:.0f}s>>")
            except Exception:
                pass
        if ts:
            prev_ts = ts

if __name__ == "__main__":
    main(sys.argv[1])
